-- V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet. Created the first time its id is loaded.
CREATE TABLE sheet (
    id VARCHAR(200) PRIMARY KEY
);
-- V2__sheet_today.sql
-- The sheet's today: every date decision and default date in the app uses it, never the real clock.
-- It starts as the real date when the sheet is created and is changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- V3__person.sql
-- A person on a sheet: a name (required) and a grade (A, B or C). Listed in the order added (by id).
CREATE TABLE person (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(500) NOT NULL,
    grade VARCHAR(1) NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- V4__person_name_unique.sql
-- A person's name is unique on the sheet, ignoring case and surrounding spaces; names are stored trimmed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(500) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- V5__claim.sql
-- A claim by a person on a sheet: an amount (0.00 or more, two decimals), a date and a note (may be
-- empty). Listed under its person newest first (by id, descending).
CREATE TABLE claim (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    amount DECIMAL(19, 2) NOT NULL,
    claim_date DATE NOT NULL,
    note VARCHAR(2000) NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- V6__rate.sql
-- A sheet's rate for a grade: a percent with two decimals (0.00 or more), one per grade. A grade with
-- no row has no rate.
CREATE TABLE rate (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade VARCHAR(1) NOT NULL,
    pct DECIMAL(19, 2) NOT NULL
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- V7__claim_status.sql
-- A claim's status: DRAFT (new), OPEN, SETTLED or VOID. Only OPEN and SETTLED claims count toward
-- the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
-- V8__claim_number.sql
-- A claim's number: given when it is opened, the sheet's next one (1, 2, ...), never reused. A draft
-- has none; voiding clears it. The sheet keeps the last number it gave out.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
-- V9__claim_due.sql
-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate then,
-- divided by 100, rounded half up. Null while the claim is not settled, or when the grade had no rate
-- then (its due stays live).
ALTER TABLE claim ADD COLUMN due DECIMAL(19, 2);
-- V10__rate_from.sql
-- A rate can carry a from-date: it applies from that date on (a rate with none applies from the beginning
-- of time). A grade may have several rates, one per from-date; a claim uses the one whose from-date is the
-- latest on or before its date.
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- V11__claim_opened_by.sql
-- Who opened a claim: the signed-in name that opened it. Null while it was never opened. The one who
-- opened a claim cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- V12__person_version.sql
-- The version of a person: raised by one on every save. An edit names the version it loaded and
-- is refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- V13__statement.sql
-- A person's statement: their due-total when it was taken (n/a when there was none) and the sheet's
-- today then. Their count and last one are read from here.
CREATE TABLE statement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    due_total VARCHAR(30) NOT NULL,
    taken_on DATE NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due;
-- null when it had none, n/a), until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
-- V14__period.sql
-- A sheet's periods: a name, unique on the sheet, and a from and to date, inclusive. No two periods on a
-- sheet overlap; a claim belongs to the one whose dates contain its date, or to none.
CREATE TABLE period (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name);
-- V15__period_closed.sql
-- A period can be closed: its due-total is then fixed at what it was on closing, and no claim dated in it can
-- be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
-- V16__person_retired.sql
-- The date a person is retired from (null: not retired). A person with one set counts as retired at
-- once, whatever the date; their claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- V17__person_held.sql
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own claimed and
-- due-total, the sheet's totals, a period's total); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- V18__role_clerk_limit.sql
-- A sheet's roles: a user name's role on the sheet, clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role VARCHAR(20) NOT NULL
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- The sheet's clerk limit: a clerk settles a claim only when its due is at or below it. NULL: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(19, 2);
-- V19__sheet_floor.sql
-- The sheet's floor: a claim's live due is at least it. Two decimals; a sheet starts at 1.00.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(19, 2) DEFAULT 1.00 NOT NULL;
-- V20__sheet_terms.sql
-- The sheet's terms: a claim is due by its date plus this many days. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- V21__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days it is
-- overdue. Two decimals; a sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(19, 2) DEFAULT 0.00 NOT NULL;
-- V22__person_patron.sql
-- A person's patrons: other people on the same sheet they have named, each once. Their backing is the
-- patrons' due-totals added up.
CREATE TABLE person_patron (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_unique UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
-- V23__person_grade.sql
-- A person's dated grades: each save of the person form records its grade from its from-date, replacing the
-- one recorded for that date. The person's own grade is the first one they were given, which applies from the
-- beginning of time.
CREATE TABLE person_grade (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade VARCHAR(10) NOT NULL,
    from_date DATE NOT NULL,
    CONSTRAINT person_grade_unique UNIQUE (person_id, from_date)
);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, id);
-- V24__claim_corrects.sql
-- The number of the claim a correction corrects: a correction is a claim with a negative amount, allowed only
-- when it names a SETTLED claim of the same person. Null for any other claim.
ALTER TABLE claim ADD COLUMN corrects INT;
-- V25__policy_date.sql
-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or after it
-- half to even. Null (blank) means the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- The date of the claim a correction corrects: a correction rounds by that date, not its own. Null for any other
-- claim. (The corrected claim is SETTLED, so its date never changes.)
ALTER TABLE claim ADD COLUMN corrects_date DATE;
-- V26__period_numbering.sql
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim opened is
-- numbered within its period (<period name>-<n>; X-<n> for a claim in no period). Null (blank) means off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number is now text: the sheet-wide 1, 2, ... or a per-period P1-1, X-1. A correction names it the same way.
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(255);
-- The last number given out in each per-period sequence of a sheet: seq is 'P:<period name>' or 'X' (no period).
CREATE TABLE claim_sequence (
    sheet_id VARCHAR(255) NOT NULL,
    seq VARCHAR(255) NOT NULL,
    last_number INT NOT NULL,
    PRIMARY KEY (sheet_id, seq)
);
-- V27__claim_listed.sql
-- Where a claim is listed under its person: newest first by this key (then by id). A new claim takes the next
-- key; a claim moved to another person takes the next key again, so it is listed as that person's newest claim.
CREATE SEQUENCE claim_listed_seq START WITH 1;
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq;
ALTER TABLE claim ALTER COLUMN listed SET DEFAULT NEXT VALUE FOR claim_listed_seq;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
-- V28__grade_terms_due_by.sql
-- The sheet's terms per grade (A, B, C): a claim of a person with that grade is due by its date plus this many days.
-- Null (blank) means the grade uses the sheet's terms.
ALTER TABLE sheet ADD COLUMN terms_a INT;
ALTER TABLE sheet ADD COLUMN terms_b INT;
ALTER TABLE sheet ADD COLUMN terms_c INT;
-- A claim's due-by, fixed when it is created: its date plus the terms of its person's grade in force on its date.
-- It does not change when the terms or the claim's date change later. Existing claims take their date plus the
-- sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD('DAY', (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- V29__claim_log.sql
-- A claim's status log: one line per status it has had, oldest first (by id) — the status, who made the change,
-- the sheet's today then and the claim's due as it was worked out at that moment (null: n/a).
CREATE TABLE claim_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) NOT NULL,
    claim_id BIGINT NOT NULL,
    status VARCHAR(10) NOT NULL,
    by_user VARCHAR(255) NOT NULL,
    on_date DATE NOT NULL,
    due DECIMAL(19, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id);
-- V30__person_hold.sql
-- A person's holds over time: each from a date on, to a date (inclusive; null: open-ended). Their OPEN claims
-- dated within a hold count in no live total, unless a statement binds them; their other claims still count.
-- Replaces the single held flag: a person held before is held from the beginning of time.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- V31__rate_to.sql
-- A rate can carry a to-date: it applies through that date (none: on and on). A claim dated after the to-date
-- of the rate that would apply to it has no rate (n/a), unless a later rate is in force then.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- V32__sheet_cap.sql
-- The sheet's cap: a person's due-total is at most it. Two decimals; null (blank) when there is none.
ALTER TABLE sheet ADD COLUMN cap DECIMAL(19, 2);
-- V33__period_person_total.sql
-- Each person's due-total fixed when a period was closed; the rows go when it is reopened. A person with no
-- row for a closed period (added after it was closed) shows 0.00 for it.
CREATE TABLE period_person_total (
    period_id BIGINT NOT NULL REFERENCES period (id),
    person_id BIGINT NOT NULL,
    total DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- V34__sheet_setting.sql
-- A sheet's dated settings: the value of a setting that carries a figure (floor, late-pct, terms, terms-A/B/C,
-- clerk-limit, cap) from a from-date on. The value in force on a date is the one with the latest from-date on or
-- before it; a row with no from-date applies from the beginning of time; before every from-date the sheet's
-- starting value applies (floor 1.00, late-pct 0.00, terms 14; none for the others). The value is as the screen
-- shows it; null (blank) for none. The sheet's old setting columns are no longer read: their values are carried
-- over here, from the beginning of time.
CREATE TABLE sheet_setting (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(40) NOT NULL,
    from_date DATE,
    setting_value VARCHAR(40)
);
CREATE INDEX sheet_setting_sheet ON sheet_setting (sheet_id, setting_key);
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'floor', CAST(floor AS VARCHAR) FROM sheet WHERE floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'late-pct', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-A', CAST(terms_a AS VARCHAR) FROM sheet WHERE terms_a IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-B', CAST(terms_b AS VARCHAR) FROM sheet WHERE terms_b IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-C', CAST(terms_c AS VARCHAR) FROM sheet WHERE terms_c IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'clerk-limit', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'cap', CAST(cap AS VARCHAR) FROM sheet WHERE cap IS NOT NULL;
-- V35__claim_deferred.sql
-- The date an OPEN claim is deferred until: while the sheet's today is before it the claim counts in no total, is not
-- overdue, cannot be settled and is left unbound by a statement. Null for a claim never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- V36__claim_proofs.sql
-- A claim's proofs count: raised by one at a time (not on a SETTLED or VOID claim); 0 for every claim to begin with.
ALTER TABLE claim ADD COLUMN proofs INT DEFAULT 0 NOT NULL;
-- V37__claim_split_from.sql
-- The number of the claim a claim was split off from; null for any claim not made by a split.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(255);
-- V38__person_watch.sql
-- Who watches a person: one row per signed-in name watching them, in the order they started watching.
-- Stopping watching removes the row; starting again adds a new one at the end.
CREATE TABLE person_watch (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
-- V39__delegation.sql
-- A sheet's delegations: a steward (by_name) delegates the steward role to a user name from a from-date to a
-- to-date, inclusive, by the sheet's today.
CREATE TABLE sheet_delegation (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    by_name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL
);
-- V40__sheet_archived.sql
-- Whether the sheet is archived: a steward archives it, and from then on everything stays visible and every change
-- is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
-- V41__person_terms.sql
-- A person's own terms: a claim of theirs is due by its date plus this many days, ahead of their grade's terms and
-- the sheet's. Null (blank) means they have none.
ALTER TABLE person ADD COLUMN terms INT;
-- V42__claim_lock.sql
-- Who holds a claim's editor open: the signed-in name that opened it, so no one else can edit the claim until it is
-- saved or cancelled, or the sheet's today changes. Null while no editor holds it.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
-- V43__period_soft_close.sql
-- A soft-closed period: its due-total and each person's are fixed (as on closing), but claims dated in it can
-- still be added, edited and change status. A claim added while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- V44__as_of_history.sql
-- What each change was made on (the sheet's today then), so a statement can be taken as of a date: every change
-- made while the sheet's today was on or before that date counts, every later one does not. Null: made before
-- this was recorded, and counts as of any date.
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
-- A statement's date is the one it was taken as of (the sheet's today when none was given); made_on is the
-- sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN made_on DATE;
-- Every rate set, in the order set: replayed up to a date it gives the rates as they stood at the end of it.
CREATE TABLE rate_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    grade VARCHAR(10) NOT NULL,
    pct DECIMAL(19, 2) NOT NULL,
    from_date DATE,
    to_date DATE,
    made_on DATE NOT NULL
);
CREATE INDEX rate_log_sheet ON rate_log (sheet_id, id);
-- Every setting set (dated, undated, the policy date), in the order set: replayed likewise.
CREATE TABLE setting_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    setting_key VARCHAR(100) NOT NULL,
    from_date DATE,
    setting_value VARCHAR(200),
    made_on DATE NOT NULL
);
CREATE INDEX setting_log_sheet ON setting_log (sheet_id, id);
-- Every binding of a person's claims, in the order made: a statement's (the claims it bound, each with its figure)
-- or a cancel's (none bound). The last one made on or before a date gives the claims bound at the end of it.
CREATE TABLE binding_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    person_id BIGINT NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX binding_log_person ON binding_log (person_id, id);
CREATE TABLE binding_log_claim (
    binding_id BIGINT NOT NULL REFERENCES binding_log (id),
    claim_id BIGINT NOT NULL,
    stated_due DECIMAL(19, 2)
);
-- V45__entity_history.sql
-- Every state a sheet's claim, person, dated grade, period, patron, watch, role, delegation and statement has been
-- saved in, with the sheet's today when it was saved, in the order saved: the last one saved while the sheet's today
-- was on or before a date gives the thing as it stood at the end of that date (an as-of view). A null state: it was
-- deleted then. A thing with no state recorded was saved before this was kept, and stands as it is as of any date.
CREATE TABLE entity_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    kind VARCHAR(40) NOT NULL,
    entity_id BIGINT NOT NULL,
    made_on DATE NOT NULL,
    state CLOB
);
CREATE INDEX entity_history_sheet ON entity_history (sheet_id, kind, id);
-- The sheet's today when it was archived (null: not archived, or not recorded).
ALTER TABLE sheet ADD COLUMN archived_on DATE;
-- V46__sheet_entry_date.sql
-- The sheet's entry date: while it is set, it is the default date of a new claim wherever the sheet's today was
-- (the claim form, the quick-add bar, a pasted line with a blank date, a correction). Null (blank) means off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
-- V47__claim_reminded.sql
-- The last sheet's today a reminder was written for an OPEN or PENDING claim; null for a claim never reminded.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- V48__holiday.sql
-- A sheet's holidays: dates, each on the sheet at most once. A claim's due-by, fixed when it is added, is moved
-- past the holidays on the sheet then.
CREATE TABLE holiday (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    holiday_date DATE NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);
-- V49__claim_due_terms.sql
-- Terms count business days. A claim keeps the date and the terms its due-by was fixed with; its due-by is the
-- terms-th business day after that date (skipping Saturdays, Sundays and the sheet's holidays now), worked out again
-- whenever the sheet's holidays change. Existing claims take their date and the days from it to their due-by; their
-- due-by is worked out again by the next migration.
ALTER TABLE claim ADD COLUMN due_from DATE;
ALTER TABLE claim ADD COLUMN due_terms INT;
UPDATE claim SET due_from = claim_date, due_terms = GREATEST(0, DATEDIFF('DAY', claim_date, due_by));
ALTER TABLE claim ALTER COLUMN due_from SET NOT NULL;
ALTER TABLE claim ALTER COLUMN due_terms SET NOT NULL;
-- V51__claim_ref.sql
-- A claim's external reference (trimmed); null for a claim with none. Unique on its sheet, ignoring case.
ALTER TABLE claim ADD COLUMN ref VARCHAR(255);
-- V52__claim_tags.sql
-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; null for a claim with none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1024);
-- Every tag the claim has ever carried, sorted and comma separated; null while it never had any.
ALTER TABLE claim ADD COLUMN tags_used VARCHAR(1024);
-- V53__void_reason.sql
-- A sheet's void reasons: trimmed texts, each on the sheet at most once. While the sheet has any, a claim is voided
-- only with one of them.
CREATE TABLE void_reason (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    reason VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);
-- The reason a VOID claim was voided with; null when it was voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
-- V54__claim_comment.sql
-- A claim's comments: one row per comment, oldest first (by id) — its trimmed text, who wrote it and the sheet's today
-- when it was written.
CREATE TABLE claim_comment (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) NOT NULL,
    claim_id BIGINT NOT NULL,
    by_user VARCHAR(255) NOT NULL,
    on_date DATE NOT NULL,
    text VARCHAR(2000) NOT NULL
);
CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, claim_id);
-- V55__claim_edited_by.sql
-- Who last edited a claim (through its form or its amount entry): the signed-in name. Null while it was never edited.
-- Like its opener, the one who last edited a claim cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
-- V56__settle_batch.sql
-- A bulk settle that settles at least one claim (one that goes PENDING counts) is a batch, numbered 1, 2, ... on the
-- sheet in the order the batches happen. The sheet keeps the last batch number it gave out (0: none yet); a claim
-- keeps the number of the batch that settled it (null when settled one at a time, or never settled). Each bulk
-- settle carries a key of its own; settle_batch maps it to the number its first settled claim took.
ALTER TABLE sheet ADD COLUMN last_settle_batch INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN settle_batch INT;
CREATE TABLE settle_batch (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    batch_key VARCHAR(255) NOT NULL,
    batch_number INT NOT NULL,
    PRIMARY KEY (sheet_id, batch_key)
);
-- V57__person_contact.sql
-- A person's contact: trimmed and lower-cased; at most one person on a sheet has a given contact. Null (blank)
-- means they have none.
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
-- V58__person_alias.sql
-- A person's aliases: other names they go by, trimmed. An alias shares the names' uniqueness on the sheet: no alias
-- equals, ignoring case, any name or other alias on it.
CREATE TABLE person_alias (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    alias VARCHAR(255) NOT NULL
);
CREATE INDEX person_alias_sheet ON person_alias (sheet_id, id);
-- V59__claim_template.sql
-- A sheet's claim templates: a trimmed name (on the sheet at most once; saving it again replaces the template), an
-- amount the claim form accepts and a trimmed note. A claim made from one copies its amount and note at that moment.
CREATE TABLE claim_template (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(255) NOT NULL,
    amount DECIMAL(19, 2) NOT NULL,
    note VARCHAR(2000) NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX claim_template_sheet_name ON claim_template (sheet_id, name);
-- V60__pool.sql
-- A sheet's pools: a trimmed name, on the sheet at most once (ignoring case).
CREATE TABLE pool (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);
-- A pool's members: a person of the sheet, in the pool at most once, with a share percent (more than 0.00, at most
-- 100.00). A person can be in several pools. A retired member's share counts as 0.00 toward the pool's total.
CREATE TABLE pool_member (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id BIGINT NOT NULL REFERENCES pool (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    share DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
-- V61__sheet_parent.sql
-- A sheet may name a parent sheet: an undated setting (key parent) whose value is a sheet's id, so the value is
-- widened to hold one (sheet ids are up to 200 long).
ALTER TABLE sheet_setting ALTER COLUMN setting_value VARCHAR(200);
-- V62__pool_member_pool.sql
-- A pool's member may instead be another pool of the sheet (member_pool_id set, person_id null), with a share like a
-- person's. A pool is a member of at most one pool, never of itself through any chain, and a chain of pools is at
-- most three deep.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);
-- V63__person_position.sql
-- A person's place in the sheet's list: the list runs by it, lowest first. Null (a person added since, or before
-- this was kept) places them by their id, so a new person goes to the end; moving a person swaps the places of
-- the two people.
ALTER TABLE person ADD COLUMN position BIGINT;
-- V64__person_origin.sql
-- The sheet a transferred person came from (null: they were not transferred here).
ALTER TABLE person ADD COLUMN origin_sheet VARCHAR(255);
-- V65__pool_member_dates.sql
-- A pool membership may carry a from-date and a to-date (either optional; the to-date not before the from-date). A
-- member whose dates do not include the sheet's today is left out of the pool's total share, balance and cuts.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
-- V66__person_retirement.sql
-- A person's past retirements, each ended by an unretire: retired from a date to the day they were unretired (the
-- sheet's today then). A claim dated after the from and before the to is refused, as one after a retirement is.
-- retire_made_on is the sheet's today when they were retired (null: not recorded); made_on when unretired.
CREATE TABLE person_retirement (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    retire_made_on DATE,
    made_on DATE NOT NULL
);
CREATE INDEX person_retirement_person ON person_retirement (person_id);

tool_use_result.stdout:
-- V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet. Created the first time its id is loaded.
CREATE TABLE sheet (
    id VARCHAR(200) PRIMARY KEY
);
-- V2__sheet_today.sql
-- The sheet's today: every date decision and default date in the app uses it, never the real clock.
-- It starts as the real date when the sheet is created and is changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- V3__person.sql
-- A person on a sheet: a name (required) and a grade (A, B or C). Listed in the order added (by id).
CREATE TABLE person (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(500) NOT NULL,
    grade VARCHAR(1) NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- V4__person_name_unique.sql
-- A person's name is unique on the sheet, ignoring case and surrounding spaces; names are stored trimmed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(500) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- V5__claim.sql
-- A claim by a person on a sheet: an amount (0.00 or more, two decimals), a date and a note (may be
-- empty). Listed under its person newest first (by id, descending).
CREATE TABLE claim (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    amount DECIMAL(19, 2) NOT NULL,
    claim_date DATE NOT NULL,
    note VARCHAR(2000) NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- V6__rate.sql
-- A sheet's rate for a grade: a percent with two decimals (0.00 or more), one per grade. A grade with
-- no row has no rate.
CREATE TABLE rate (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade VARCHAR(1) NOT NULL,
    pct DECIMAL(19, 2) NOT NULL
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- V7__claim_status.sql
-- A claim's status: DRAFT (new), OPEN, SETTLED or VOID. Only OPEN and SETTLED claims count toward
-- the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
-- V8__claim_number.sql
-- A claim's number: given when it is opened, the sheet's next one (1, 2, ...), never reused. A draft
-- has none; voiding clears it. The sheet keeps the last number it gave out.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
-- V9__claim_due.sql
-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate then,
-- divided by 100, rounded half up. Null while the claim is not settled, or when the grade had no rate
-- then (its due stays live).
ALTER TABLE claim ADD COLUMN due DECIMAL(19, 2);
-- V10__rate_from.sql
-- A rate can carry a from-date: it applies from that date on (a rate with none applies from the beginning
-- of time). A grade may have several rates, one per from-date; a claim uses the one whose from-date is the
-- latest on or before its date.
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- V11__claim_opened_by.sql
-- Who opened a claim: the signed-in name that opened it. Null while it was never opened. The one who
-- opened a claim cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- V12__person_version.sql
-- The version of a person: raised by one on every save. An edit names the version it loaded and
-- is refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- V13__statement.sql
-- A person's statement: their due-total when it was taken (n/a when there was none) and the sheet's
-- today then. Their count and last one are read from here.
CREATE TABLE statement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    due_total VARCHAR(30) NOT NULL,
    taken_on DATE NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due;
-- null when it had none, n/a), until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
-- V14__period.sql
-- A sheet's periods: a name, unique on the sheet, and a from and to date, inclusive. No two periods on a
-- sheet overlap; a claim belongs to the one whose dates contain its date, or to none.
CREATE TABLE period (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name);
-- V15__period_closed.sql
-- A period can be closed: its due-total is then fixed at what it was on closing, and no claim dated in it can
-- be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
-- V16__person_retired.sql
-- The date a person is retired from (null: not retired). A person with one set counts as retired at
-- once, whatever the date; their claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- V17__person_held.sql
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own claimed and
-- due-total, the sheet's totals, a period's total); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- V18__role_clerk_limit.sql
-- A sheet's roles: a user name's role on the sheet, clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role VARCHAR(20) NOT NULL
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- The sheet's clerk limit: a clerk settles a claim only when its due is at or below it. NULL: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(19, 2);
-- V19__sheet_floor.sql
-- The sheet's floor: a claim's live due is at least it. Two decimals; a sheet starts at 1.00.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(19, 2) DEFAULT 1.00 NOT NULL;
-- V20__sheet_terms.sql
-- The sheet's terms: a claim is due by its date plus this many days. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- V21__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days it is
-- overdue. Two decimals; a sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(19, 2) DEFAULT 0.00 NOT NULL;
-- V22__person_patron.sql
-- A person's patrons: other people on the same sheet they have named, each once. Their backing is the
-- patrons' due-totals added up.
CREATE TABLE person_patron (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_unique UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
-- V23__person_grade.sql
-- A person's dated grades: each save of the person form records its grade from its from-date, replacing the
-- one recorded for that date. The person's own grade is the first one they were given, which applies from the
-- beginning of time.
CREATE TABLE person_grade (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade VARCHAR(10) NOT NULL,
    from_date DATE NOT NULL,
    CONSTRAINT person_grade_unique UNIQUE (person_id, from_date)
);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, id);
-- V24__claim_corrects.sql
-- The number of the claim a correction corrects: a correction is a claim with a negative amount, allowed only
-- when it names a SETTLED claim of the same person. Null for any other claim.
ALTER TABLE claim ADD COLUMN corrects INT;
-- V25__policy_date.sql
-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or after it
-- half to even. Null (blank) means the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- The date of the claim a correction corrects: a correction rounds by that date, not its own. Null for any other
-- claim. (The corrected claim is SETTLED, so its date never changes.)
ALTER TABLE claim ADD COLUMN corrects_date DATE;
-- V26__period_numbering.sql
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim opened is
-- numbered within its period (<period name>-<n>; X-<n> for a claim in no period). Null (blank) means off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number is now text: the sheet-wide 1, 2, ... or a per-period P1-1, X-1. A correction names it the same way.
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(255);
-- The last number given out in each per-period sequence of a sheet: seq is 'P:<period name>' or 'X' (no period).
CREATE TABLE claim_sequence (
    sheet_id VARCHAR(255) NOT NULL,
    seq VARCHAR(255) NOT NULL,
    last_number INT NOT NULL,
    PRIMARY KEY (sheet_id, seq)
);
-- V27__claim_listed.sql
-- Where a claim is listed under its person: newest first by this key (then by id). A new claim takes the next
-- key; a claim moved to another person takes the next key again, so it is listed as that person's newest claim.
CREATE SEQUENCE claim_listed_seq START WITH 1;
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq;
ALTER TABLE claim ALTER COLUMN listed SET DEFAULT NEXT VALUE FOR claim_listed_seq;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
-- V28__grade_terms_due_by.sql
-- The sheet's terms per grade (A, B, C): a claim of a person with that grade is due by its date plus this many days.
-- Null (blank) means the grade uses the sheet's terms.
ALTER TABLE sheet ADD COLUMN terms_a INT;
ALTER TABLE sheet ADD COLUMN terms_b INT;
ALTER TABLE sheet ADD COLUMN terms_c INT;
-- A claim's due-by, fixed when it is created: its date plus the terms of its person's grade in force on its date.
-- It does not change when the terms or the claim's date change later. Existing claims take their date plus the
-- sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD('DAY', (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- V29__claim_log.sql
-- A claim's status log: one line per status it has had, oldest first (by id) — the status, who made the change,
-- the sheet's today then and the claim's due as it was worked out at that moment (null: n/a).
CREATE TABLE claim_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) NOT NULL,
    claim_id BIGINT NOT NULL,
    status VARCHAR(10) NOT NULL,
    by_user VARCHAR(255) NOT NULL,
    on_date DATE NOT NULL,
    due DECIMAL(19, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id);
-- V30__person_hold.sql
-- A person's holds over time: each from a date on, to a date (inclusive; null: open-ended). Their OPEN claims
-- dated within a hold count in no live total, unless a statement binds them; their other claims still count.
-- Replaces the single held flag: a person held before is held from the beginning of time.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- V31__rate_to.sql
-- A rate can carry a to-date: it applies through that date (none: on and on). A claim dated after the to-date
-- of the rate that would apply to it has no rate (n/a), unless a later rate is in force then.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- V32__sheet_cap.sql
-- The sheet's cap: a person's due-total is at most it. Two decimals; null (blank) when there is none.
ALTER TABLE sheet ADD COLUMN cap DECIMAL(19, 2);
-- V33__period_person_total.sql
-- Each person's due-total fixed when a period was closed; the rows go when it is reopened. A person with no
-- row for a closed period (added after it was closed) shows 0.00 for it.
CREATE TABLE period_person_total (
    period_id BIGINT NOT NULL REFERENCES period (id),
    person_id BIGINT NOT NULL,
    total DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- V34__sheet_setting.sql
-- A sheet's dated settings: the value of a setting that carries a figure (floor, late-pct, terms, terms-A/B/C,
-- clerk-limit, cap) from a from-date on. The value in force on a date is the one with the latest from-date on or
-- before it; a row with no from-date applies from the beginning of time; before every from-date the sheet's
-- starting value applies (floor 1.00, late-pct 0.00, terms 14; none for the others). The value is as the screen
-- shows it; null (blank) for none. The sheet's old setting columns are no longer read: their values are carried
-- over here, from the beginning of time.
CREATE TABLE sheet_setting (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(40) NOT NULL,
    from_date DATE,
    setting_value VARCHAR(40)
);
CREATE INDEX sheet_setting_sheet ON sheet_setting (sheet_id, setting_key);
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'floor', CAST(floor AS VARCHAR) FROM sheet WHERE floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'late-pct', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-A', CAST(terms_a AS VARCHAR) FROM sheet WHERE terms_a IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-B', CAST(terms_b AS VARCHAR) FROM sheet WHERE terms_b IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'terms-C', CAST(terms_c AS VARCHAR) FROM sheet WHERE terms_c IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'clerk-limit', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, setting_value)
    SELECT id, 'cap', CAST(cap AS VARCHAR) FROM sheet WHERE cap IS NOT NULL;
-- V35__claim_deferred.sql
-- The date an OPEN claim is deferred until: while the sheet's today is before it the claim counts in no total, is not
-- overdue, cannot be settled and is left unbound by a statement. Null for a claim never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- V36__claim_proofs.sql
-- A claim's proofs count: raised by one at a time (not on a SETTLED or VOID claim); 0 for every claim to begin with.
ALTER TABLE claim ADD COLUMN proofs INT DEFAULT 0 NOT NULL;
-- V37__claim_split_from.sql
-- The number of the claim a claim was split off from; null for any claim not made by a split.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(255);
-- V38__person_watch.sql
-- Who watches a person: one row per signed-in name watching them, in the order they started watching.
-- Stopping watching removes the row; starting again adds a new one at the end.
CREATE TABLE person_watch (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
-- V39__delegation.sql
-- A sheet's delegations: a steward (by_name) delegates the steward role to a user name from a from-date to a
-- to-date, inclusive, by the sheet's today.
CREATE TABLE sheet_delegation (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    by_name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL
);
-- V40__sheet_archived.sql
-- Whether the sheet is archived: a steward archives it, and from then on everything stays visible and every change
-- is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
-- V41__person_terms.sql
-- A person's own terms: a claim of theirs is due by its date plus this many days, ahead of their grade's terms and
-- the sheet's. Null (blank) means they have none.
ALTER TABLE person ADD COLUMN terms INT;
-- V42__claim_lock.sql
-- Who holds a claim's editor open: the signed-in name that opened it, so no one else can edit the claim until it is
-- saved or cancelled, or the sheet's today changes. Null while no editor holds it.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
-- V43__period_soft_close.sql
-- A soft-closed period: its due-total and each person's are fixed (as on closing), but claims dated in it can
-- still be added, edited and change status. A claim added while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- V44__as_of_history.sql
-- What each change was made on (the sheet's today then), so a statement can be taken as of a date: every change
-- made while the sheet's today was on or before that date counts, every later one does not. Null: made before
-- this was recorded, and counts as of any date.
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
-- A statement's date is the one it was taken as of (the sheet's today when none was given); made_on is the
-- sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN made_on DATE;
-- Every rate set, in the order set: replayed up to a date it gives the rates as they stood at the end of it.
CREATE TABLE rate_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    grade VARCHAR(10) NOT NULL,
    pct DECIMAL(19, 2) NOT NULL,
    from_date DATE,
    to_date DATE,
    made_on DATE NOT NULL
);
CREATE INDEX rate_log_sheet ON rate_log (sheet_id, id);
-- Every setting set (dated, undated, the policy date), in the order set: replayed likewise.
CREATE TABLE setting_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    setting_key VARCHAR(100) NOT NULL,
    from_date DATE,
    setting_value VARCHAR(200),
    made_on DATE NOT NULL
);
CREATE INDEX setting_log_sheet ON setting_log (sheet_id, id);
-- Every binding of a person's claims, in the order made: a statement's (the claims it bound, each with its figure)
-- or a cancel's (none bound). The last one made on or before a date gives the claims bound at the end of it.
CREATE TABLE binding_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    person_id BIGINT NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX binding_log_person ON binding_log (person_id, id);
CREATE TABLE binding_log_claim (
    binding_id BIGINT NOT NULL REFERENCES binding_log (id),
    claim_id BIGINT NOT NULL,
    stated_due DECIMAL(19, 2)
);
-- V45__entity_history.sql
-- Every state a sheet's claim, person, dated grade, period, patron, watch, role, delegation and statement has been
-- saved in, with the sheet's today when it was saved, in the order saved: the last one saved while the sheet's today
-- was on or before a date gives the thing as it stood at the end of that date (an as-of view). A null state: it was
-- deleted then. A thing with no state recorded was saved before this was kept, and stands as it is as of any date.
CREATE TABLE entity_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    kind VARCHAR(40) NOT NULL,
    entity_id BIGINT NOT NULL,
    made_on DATE NOT NULL,
    state CLOB
);
CREATE INDEX entity_history_sheet ON entity_history (sheet_id, kind, id);
-- The sheet's today when it was archived (null: not archived, or not recorded).
ALTER TABLE sheet ADD COLUMN archived_on DATE;
-- V46__sheet_entry_date.sql
-- The sheet's entry date: while it is set, it is the default date of a new claim wherever the sheet's today was
-- (the claim form, the quick-add bar, a pasted line with a blank date, a correction). Null (blank) means off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
-- V47__claim_reminded.sql
-- The last sheet's today a reminder was written for an OPEN or PENDING claim; null for a claim never reminded.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- V48__holiday.sql
-- A sheet's holidays: dates, each on the sheet at most once. A claim's due-by, fixed when it is added, is moved
-- past the holidays on the sheet then.
CREATE TABLE holiday (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    holiday_date DATE NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);
-- V49__claim_due_terms.sql
-- Terms count business days. A claim keeps the date and the terms its due-by was fixed with; its due-by is the
-- terms-th business day after that date (skipping Saturdays, Sundays and the sheet's holidays now), worked out again
-- whenever the sheet's holidays change. Existing claims take their date and the days from it to their due-by; their
-- due-by is worked out again by the next migration.
ALTER TABLE claim ADD COLUMN due_from DATE;
ALTER TABLE claim ADD COLUMN due_terms INT;
UPDATE claim SET due_from = claim_date, due_terms = GREATEST(0, DATEDIFF('DAY', claim_date, due_by));
ALTER TABLE claim ALTER COLUMN due_from SET NOT NULL;
ALTER TABLE claim ALTER COLUMN due_terms SET NOT NULL;
-- V51__claim_ref.sql
-- A claim's external reference (trimmed); null for a claim with none. Unique on its sheet, ignoring case.
ALTER TABLE claim ADD COLUMN ref VARCHAR(255);
-- V52__claim_tags.sql
-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; null for a claim with none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1024);
-- Every tag the claim has ever carried, sorted and comma separated; null while it never had any.
ALTER TABLE claim ADD COLUMN tags_used VARCHAR(1024);
-- V53__void_reason.sql
-- A sheet's void reasons: trimmed texts, each on the sheet at most once. While the sheet has any, a claim is voided
-- only with one of them.
CREATE TABLE void_reason (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    reason VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);
-- The reason a VOID claim was voided with; null when it was voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
-- V54__claim_comment.sql
-- A claim's comments: one row per comment, oldest first (by id) — its trimmed text, who wrote it and the sheet's today
-- when it was written.
CREATE TABLE claim_comment (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) NOT NULL,
    claim_id BIGINT NOT NULL,
    by_user VARCHAR(255) NOT NULL,
    on_date DATE NOT NULL,
    text VARCHAR(2000) NOT NULL
);
CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, claim_id);
-- V55__claim_edited_by.sql
-- Who last edited a claim (through its form or its amount entry): the signed-in name. Null while it was never edited.
-- Like its opener, the one who last edited a claim cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
-- V56__settle_batch.sql
-- A bulk settle that settles at least one claim (one that goes PENDING counts) is a batch, numbered 1, 2, ... on the
-- sheet in the order the batches happen. The sheet keeps the last batch number it gave out (0: none yet); a claim
-- keeps the number of the batch that settled it (null when settled one at a time, or never settled). Each bulk
-- settle carries a key of its own; settle_batch maps it to the number its first settled claim took.
ALTER TABLE sheet ADD COLUMN last_settle_batch INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN settle_batch INT;
CREATE TABLE settle_batch (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    batch_key VARCHAR(255) NOT NULL,
    batch_number INT NOT NULL,
    PRIMARY KEY (sheet_id, batch_key)
);
-- V57__person_contact.sql
-- A person's contact: trimmed and lower-cased; at most one person on a sheet has a given contact. Null (blank)
-- means they have none.
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
-- V58__person_alias.sql
-- A person's aliases: other names they go by, trimmed. An alias shares the names' uniqueness on the sheet: no alias
-- equals, ignoring case, any name or other alias on it.
CREATE TABLE person_alias (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    alias VARCHAR(255) NOT NULL
);
CREATE INDEX person_alias_sheet ON person_alias (sheet_id, id);
-- V59__claim_template.sql
-- A sheet's claim templates: a trimmed name (on the sheet at most once; saving it again replaces the template), an
-- amount the claim form accepts and a trimmed note. A claim made from one copies its amount and note at that moment.
CREATE TABLE claim_template (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(255) NOT NULL,
    amount DECIMAL(19, 2) NOT NULL,
    note VARCHAR(2000) NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX claim_template_sheet_name ON claim_template (sheet_id, name);
-- V60__pool.sql
-- A sheet's pools: a trimmed name, on the sheet at most once (ignoring case).
CREATE TABLE pool (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);
-- A pool's members: a person of the sheet, in the pool at most once, with a share percent (more than 0.00, at most
-- 100.00). A person can be in several pools. A retired member's share counts as 0.00 toward the pool's total.
CREATE TABLE pool_member (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id BIGINT NOT NULL REFERENCES pool (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    share DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
-- V61__sheet_parent.sql
-- A sheet may name a parent sheet: an undated setting (key parent) whose value is a sheet's id, so the value is
-- widened to hold one (sheet ids are up to 200 long).
ALTER TABLE sheet_setting ALTER COLUMN setting_value VARCHAR(200);
-- V62__pool_member_pool.sql
-- A pool's member may instead be another pool of the sheet (member_pool_id set, person_id null), with a share like a
-- person's. A pool is a member of at most one pool, never of itself through any chain, and a chain of pools is at
-- most three deep.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);
-- V63__person_position.sql
-- A person's place in the sheet's list: the list runs by it, lowest first. Null (a person added since, or before
-- this was kept) places them by their id, so a new person goes to the end; moving a person swaps the places of
-- the two people.
ALTER TABLE person ADD COLUMN position BIGINT;
-- V64__person_origin.sql
-- The sheet a transferred person came from (null: they were not transferred here).
ALTER TABLE person ADD COLUMN origin_sheet VARCHAR(255);
-- V65__pool_member_dates.sql
-- A pool membership may carry a from-date and a to-date (either optional; the to-date not before the from-date). A
-- member whose dates do not include the sheet's today is left out of the pool's total share, balance and cuts.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
-- V66__person_retirement.sql
-- A person's past retirements, each ended by an unretire: retired from a date to the day they were unretired (the
-- sheet's today then). A claim dated after the from and before the to is refused, as one after a retirement is.
-- retire_made_on is the sheet's today when they were retired (null: not recorded); made_on when unretired.
CREATE TABLE person_retirement (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    retire_made_on DATE,
    made_on DATE NOT NULL
);
CREATE INDEX person_retirement_person ON person_retirement (person_id);

