package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** The step after GuardViewer on every change: refuses it, before anything is read or written, when the sheet is
 *  archived (an archived sheet shows everything and changes nothing). */
public class GuardArchived {
    public void guard(@PathVariable("sheetId") String sheetId, SheetRepository repository)
            throws SheetArchivedException {
        if (repository.findById(sheetId.trim()).map(Sheet::isArchived).orElse(false)) {
            throw new SheetArchivedException("The sheet is archived: nothing on it can be changed.");
        }
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import net.officefloor.hq.app.role.RoleRepository;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The records that only report figures: they never carry the steward a delegate acts for. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    private final ObjectProvider<RoleRepository> roles;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<RoleRepository> roles) {
        this.file = Path.of(path);
        this.roles = roles;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A record of a change made by a user
     *  name while the sheet's today is inside a delegation of the steward role to it ends with for=&lt;the steward
     *  who delegated&gt;. */
    public void record(String entry) {
        write(entry + forDelegator(entry));
    }

    /** " for=&lt;steward&gt;" when the record's by= acts for a steward on its sheet= today, else "". */
    private String forDelegator(String entry) {
        int space = entry.indexOf(' ');
        if (space < 0 || FIGURES.contains(entry.substring(0, space))) {
            return "";
        }
        String sheet = field(entry, "sheet");
        String by = field(entry, "by");
        if (sheet == null || by == null || by.isEmpty()) {
            return "";
        }
        String delegator = roles.getObject().delegatorOf(sheet, by);
        return delegator == null ? "" : " for=" + delegator;
    }

    private static String field(String entry, String name) {
        String key = " " + name + "=";
        int start = entry.indexOf(key);
        if (start < 0) {
            return null;
        }
        start += key.length();
        int end = entry.indexOf(' ', start);
        return end < 0 ? entry.substring(start) : entry.substring(start, end);
    }

    private synchronized void write(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Every line the file holds for a sheet (carrying sheet=&lt;id&gt;), in the order they were written. */
    public synchronized java.util.List<String> linesOf(String sheetId) {
        String token = "sheet=" + sheetId;
        try {
            if (!Files.exists(file)) {
                return java.util.List.of();
            }
            return Files.readAllLines(file, StandardCharsets.UTF_8).stream()
                    .filter(line -> java.util.Arrays.asList(line.split(" ")).contains(token))
                    .toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

/** The signed-in name a change was made by, as the screen sends it in the URI-encoded X-User header. */
public final class AuditUser {

    private AuditUser() {
    }

    public static String decode(String header) {
        return header == null ? "" : URLDecoder.decode(header.replace("+", "%2B"), StandardCharsets.UTF_8).trim();
    }
}
package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A user name's role on a sheet: clerk, steward or viewer. A name with none is a clerk. */
@Entity
@Table(name = "sheet_role")
public class Role {

    public static final String CLERK = "clerk";

    public static final String STEWARD = "steward";

    /** Sees every screen and figure and can change nothing. */
    public static final String VIEWER = "viewer";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(nullable = false)
    private String role;

    protected Role() {
    }

    public Role(String sheetId, String userName, String role) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUserName() {
        return userName;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface RoleRepository extends JpaRepository<Role, Long> {

    List<Role> findBySheetIdOrderByUserNameAsc(String sheetId);

    Optional<Role> findBySheetIdAndUserName(String sheetId, String userName);

    /** The role the user name acts in on the sheet: steward while the sheet's today is inside a delegation to it,
     *  else its own role. */
    default String roleOf(String sheetId, String userName) {
        String own = ownRoleOf(sheetId, userName);
        return !Role.STEWARD.equals(own) && delegatorOf(sheetId, userName) != null ? Role.STEWARD : own;
    }

    /** The user name's own role on the sheet, leaving delegations aside: clerk unless one is set. */
    default String ownRoleOf(String sheetId, String userName) {
        return findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /** The steward the user name acts for on the sheet's today (the latest delegation to it covering that day), or
     *  null when none. */
    default String delegatorOf(String sheetId, String userName) {
        List<String> by = activeDelegators(sheetId, userName);
        return by.isEmpty() ? null : by.get(0);
    }

    @Query("select d.byName from Delegation d, Sheet s where s.id = :sheetId and d.sheetId = :sheetId"
            + " and d.userName = :userName and d.fromDate <= s.today and d.toDate >= s.today order by d.id desc")
    List<String> activeDelegators(@Param("sheetId") String sheetId, @Param("userName") String userName);
}
