package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records, after the change's own lines, each person whose figures the change moved, then the sheet's totals
 *  when they moved. */
public class AuditRollup {
    public void audit(@PathVariable("sheetId") String sheetId, @Val Rollup before, SheetRepository sheets,
            PersonRepository people, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        Rollup now = Rollup.of(sheetId, sheets, people, claims, rates, grades);
        now.changesSince(before, sheetId, AuditUser.decode(user)).forEach(audit::record);
    }
}
package net.officefloor.hq.app.rollup;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** When the sheet's today changes, records each person's due-total as it stood on the day being left, before the
 *  change takes effect (so before any period closes and before the change's rollup lines). */
public class AuditSnapshot {
    public void audit(@Val LocalDate today, @Val Sheet sheet, @Val Rollup before,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        if (today.equals(sheet.getToday())) {
            return;
        }
        before.snapshot(sheet.getId(), AuditUser.decode(user)).forEach(audit::record);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGrade;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonGrades;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * The sheet's figures at one moment, as the screen shows them: each person's claimed and due-total, in the
 * order they were added, and the sheet's claimed-total and due-total (everyone's added up, skipping n/a), and each
 * person's and the sheet's overdue-total (their counted overdue claims' dues, with late charge, skipping n/a).
 * The sheet's due-total and overdue-total leave out the single highest and lowest figure when there are three or more.
 * A person's OPEN and PENDING claims dated within a hold of theirs, or all of them once their retirement date is
 * reached, count in none of them, unless a statement binds them.
 */
public class Rollup {

    /** One person's figures. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    private final Map<Long, Figures> people;
    private final String claimedTotal;
    private final String dueTotal;
    private final String overdueTotal;

    private Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
        this.people = people;
        this.claimedTotal = claimedTotal;
        this.dueTotal = dueTotal;
        this.overdueTotal = overdueTotal;
    }

    /** Works out the sheet's figures now; a sheet not yet stored has none. */
    public static Rollup of(String sheetId, SheetRepository sheets, PersonRepository persons,
            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades) {
        String id = sheetId.trim();
        Optional<Sheet> sheet = sheets.findById(id);
        Map<Long, Figures> people = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        if (sheet.isPresent()) {
            List<Claim> all = claims.findBySheetIdOrderByIdDesc(id);
            var sheetRates = rates.findInChain(id);
            Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(id);
            for (Person person : persons.findListed(id)) {
                List<Claim> mine = all.stream().filter(c -> person.getId().equals(c.getPersonId())).toList();
                BigDecimal claimed = mine.stream().filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday())).map(Claim::getAmount)
                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
                ClaimFigures figures = new ClaimFigures(sheetRates,
                        new PersonGrades(person.getGrade(), dated.getOrDefault(person.getId(), List.of())), sheet.get());
                String due = figures.dueTotal(mine, sheet.get().getToday(), person);
                BigDecimal overdue = mine.stream()
                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && figures.overdue(c))
                        .map(figures::due).filter(d -> d != null)
                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
                people.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), due,
                        overdue.toPlainString()));
                overdues.add(overdue);
                claimedTotal = claimedTotal.add(claimed);
                if (!"n/a".equals(due)) {
                    dues.add(new BigDecimal(due));
                }
            }
        }
        return new Rollup(people, claimedTotal.setScale(2).toPlainString(), trimmedSum(dues),
                trimmedSum(overdues));
    }

    /** Adds up people's figures; with three or more, the single highest and the single lowest are left out. */
    private static String trimmedSum(List<BigDecimal> figures) {
        List<BigDecimal> sorted = figures.stream().sorted().toList();
        List<BigDecimal> kept = sorted.size() >= 3 ? sorted.subList(1, sorted.size() - 1) : sorted;
        return kept.stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
    }

    /** One SNAPSHOT line per person, in list order, with the due-total as it stands in these figures. */
    public List<String> snapshot(String sheetId, String user) {
        String head = " sheet=" + sheetId.trim() + " by=" + user;
        List<String> lines = new ArrayList<>();
        people.values().forEach(f -> lines.add("SNAPSHOT" + head + " name=" + f.name() + " due-total=" + f.dueTotal()));
        return lines;
    }

    /** The audit lines telling how the figures moved from before to now: one per person whose figures changed
     *  (or who is new), then the totals when they changed; none when nothing moved. */
    public List<String> changesSince(Rollup before, String sheetId, String user) {
        String head = " sheet=" + sheetId.trim() + " by=" + user;
        List<String> lines = new ArrayList<>();
        people.forEach((id, now) -> {
            Figures was = before.people.get(id);
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
                    || !was.overdueTotal().equals(now.overdueTotal())) {
                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
                        + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        });
        if (!before.claimedTotal.equals(claimedTotal) || !before.dueTotal.equals(dueTotal)
                || !before.overdueTotal.equals(overdueTotal)) {
            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
                    + " overdue-total=" + overdueTotal);
        }
        return lines;
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Notes the sheet's figures before the change, so the audit can tell afterwards which of them moved. */
public class TakeRollup {
    public void take(@PathVariable("sheetId") String sheetId, SheetRepository sheets, PersonRepository people,
            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades, Out<Rollup> before) {
        before.set(Rollup.of(sheetId, sheets, people, claims, rates, grades));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the transfer, once it is saved: on the sheet left, then its rollup lines; on the sheet arrived on, then
 *  its rollup lines. */
public class AuditPersonTransferred {
    public void audit(@Val PersonTransferred transferred, @Val Rollup before, SheetRepository sheets,
            PersonRepository people, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String userHeader, Audit audit) {
        String user = AuditUser.decode(userHeader);
        String from = transferred.fromSheet();
        String to = transferred.toSheet();
        audit.record("PERSON_TRANSFERRED sheet=" + from + " by=" + user + " name=" + transferred.name() + " to=" + to);
        Rollup.of(from, sheets, people, claims, rates, grades).changesSince(before, from, user)
                .forEach(audit::record);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + user + " name=" + transferred.name() + " from=" + from);
        Rollup.of(to, sheets, people, claims, rates, grades).changesSince(transferred.toBefore(), to, user)
                .forEach(audit::record);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;

/** A transfer done: the person's name, the sheet they left, the sheet they arrived on, and that sheet's figures
 *  before they arrived. */
public record PersonTransferred(String name, String fromSheet, String toSheet, Rollup toBefore) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads from the body the id of the sheet to transfer the person to. */
public class ValidateTransfer {

    public record TransferRequest(String toSheet) {
    }

    public void validate(@RequestBody(required = false) TransferRequest request, Out<TransferInput> body)
            throws InvalidPersonException {
        String to = request == null || request.toSheet() == null ? "" : request.toSheet().trim();
        if (to.isEmpty()) {
            throw new InvalidPersonException("Enter the id of the sheet to transfer to.");
        }
        if (to.length() > 200) {
            throw new InvalidPersonException("A sheet id is at most 200 characters.");
        }
        body.set(new TransferInput(to));
    }
}
package net.officefloor.hq.app.person;

/** A validated transfer request: the id of the sheet to transfer the person to, trimmed. */
public record TransferInput(String toSheet) {
}
package net.officefloor.hq.app.person;

import net.officefloor.web.ObjectResponse;
import net.officefloor.plugin.variable.Val;

/** Responds with where the person went. */
public class RespondWithTransferred {

    public record TransferredResponse(String name, String toSheet) {
    }

    public void respond(@Val PersonTransferred transferred, ObjectResponse<TransferredResponse> response) {
        response.send(new TransferredResponse(transferred.name(), transferred.toSheet()));
    }
}
